INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bfc5af54-2cb3-4674-b014-b5a747ba4bd8', '21feff02-016d-46e2-bb9d-c27495133b1b', '60. óra: Tengelyes szimmetria', 'Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "337dc396-0b6c-4d5f-8560-0193359c41e6", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "0602f8e0-ce6f-4d17-9cd4-1936786ba343", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "6fb34df7-07ea-4224-85a1-12498c58f363", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "0de2d16d-2d48-4e2b-870f-b3e3e221c5c4", "text": "Ha kerek", "isCorrect": false}, {"id": "1a5cf083-5a20-48b0-9e3a-4628e34dd82f", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "395826c8-b5be-440a-a968-4aceb3b012ef", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "f59d7673-b327-40bb-baae-21701618528e", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "f0c9f1e4-ccbf-4161-b418-1ac06fcf87b4", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "2dc94341-bdab-4e5c-b325-f2319e872b49", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "0fb1c377-c3ca-4836-9f02-5576ffb6552c", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "dfda6518-5b8a-4fd1-aa98-6f4c0f4027ec", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "620e822b-a5e7-4bc7-88d6-08edf5b63438", "text": "Igaz", "isCorrect": true}, {"id": "510b815a-a105-4772-bd3e-2c7ee79aab45", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bebda998-7b6c-4a9e-9736-78dd11b5a268", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "9244e74c-e25e-4423-b452-9109809c0fbe", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "3fcc63bc-3959-4bce-b969-5465ad3ec1fe", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "fc11a9bf-acdc-4c51-9c95-29ea1046f8a0", "text": "1", "isCorrect": false}, {"id": "b10dc09c-78b3-41cd-8b9a-ac4555b39256", "text": "2", "isCorrect": false}, {"id": "67b517ed-64d8-44c1-9ce7-0e918df77dbb", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "ce47644c-4a4b-40dc-a12d-61eae7f9a293", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "61a5568d-01a7-45b3-bcea-76c7afb874b6", "text": "Igaz", "isCorrect": true}, {"id": "93889259-24d8-4b0a-9e81-e44e3abf23de", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a2ad3a6e-eba2-4a0e-a2e9-e80150adc1ac", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('46368c80-6a4d-4f1f-a0af-53c7c29d29fe', '21feff02-016d-46e2-bb9d-c27495133b1b', '61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek', 'Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "a0b057ca-35fb-479c-a825-383716147302", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "85dbb3eb-63cb-457d-85d2-df8c031c4957", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "276c1ab6-97d3-4d0d-a105-a8066ca1df2d", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "0b7531ee-55a9-4e2f-8aeb-2095f30ea80f", "text": "Igaz", "isCorrect": true}, {"id": "53efa969-7cf4-4e94-a7c3-b515e6c26712", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6a05bf78-17ec-47dc-874c-4665c9da7c3d", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "e7ce1ded-a036-407e-bf64-bc0ce8fa3201", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "9aa7e520-9a54-4b2e-ad32-d23ee4e6c827", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "88d71d37-af7e-4080-b1d4-88272b2f41e0", "text": "Igaz", "isCorrect": true}, {"id": "a777b4e1-64a1-4956-8f9e-08d81373b531", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "80321605-0668-40e2-9302-9cb9953eb4ef", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "d036536b-645b-48f0-8eb9-29befccfb739", "text": "Igaz", "isCorrect": true}, {"id": "27d46911-48d4-4c1a-99a6-b9baeee53900", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1f89c020-603c-4221-9be8-040ee0b0a3ce', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e44e2d1f-4ffa-4a99-8215-d2dab02235d3", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "86956ead-5d1e-4384-8c47-d02d5ac7e5ec", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "480a571e-fd3c-4c33-84b7-4b376f70f04b", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "ddac74dd-eb95-469d-bfd3-1193494715c3", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "72369eaa-7e0a-4a8f-99a8-5df145328712", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "19ba1d7a-61c3-4ba4-a6d9-93d1a27bc0a4", "text": "Igaz", "isCorrect": true}, {"id": "3c210f69-4ebe-4f8d-9b50-1eedb5219e5a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6b467b47-517c-431a-9d8a-8fed9b9dc902", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "ea25325e-0635-4d85-be91-e4736f862263", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "afcd69b8-e142-46ae-90e8-15665b94ed49", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d0bc5777-50fb-46fe-bcb8-0e6aa727f517", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a67d5d9d-a060-42cf-b8f8-428cda248e00', '21feff02-016d-46e2-bb9d-c27495133b1b', '63. óra: Szerkesztési feladatok', 'Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "d6c7fe1e-cacc-4309-b55f-4fcf7213529b", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "9961159d-6a55-4ea2-9b57-62bcbb64aae9", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "621baf64-75d3-4258-865a-67a838ddd0b0", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "e345e056-2494-4353-aeec-4f1dce4b1ca9", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "81a1a74d-d244-479e-ba6e-4e3f9d59cb4b", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "9b189e19-94bc-4d7e-a974-7abb68c1a3d4", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "83329ed0-b747-4a67-9c67-7159fdb8435a", "text": "Igaz", "isCorrect": true}, {"id": "ce307dbd-47bf-4fb7-ba9f-4d4372e35a49", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "154df0ba-2092-4465-9caa-e5d3c8d7f86f", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "b61c71b1-8900-4155-8a28-85b1b50d2bef", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "b4c95859-28e1-46fb-949b-34d26fb3ee86", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "c7bac895-d085-499f-a403-523d466d8cf7", "text": "Igaz", "isCorrect": true}, {"id": "41b234ba-483b-4070-ad36-4f0a02ee98ee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7bd7d42f-e08e-4592-96a3-d16341ecfe45", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "b200b0d7-1de9-4409-8df8-10adf7eaad01", "text": "Igaz", "isCorrect": true}, {"id": "1821209f-7129-4feb-8fa4-1de80eac9da1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "94656a12-d837-48fa-985c-1bc0e49b8582", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "393a6cd8-b03e-43ce-94f6-9c003c617b7c", "text": "Igaz", "isCorrect": true}, {"id": "591b0427-cfd4-47f6-a98b-596b13719872", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2e8cf6f0-5ea5-4df7-a4dd-69d22f1c8b05', '21feff02-016d-46e2-bb9d-c27495133b1b', '64. óra: Dinamikus szerkesztőprogram megismerése', 'Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "4dec15c1-0233-40ef-9d96-a136e4946b6a", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "e0be0883-7d48-413c-8726-40b1a80ed7dc", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "e536b32d-3d3f-4f7b-959d-18a048f5895d", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "b9ee299b-de49-4bd1-a77e-b4747fa8f758", "text": "Videóvágásra", "isCorrect": false}, {"id": "905b9320-8e47-4a5f-9bec-319fd594205d", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "212cf45a-07da-4586-a1b9-eceb953372eb", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "02b0b718-b38b-48d7-87c3-f05a81995b07", "text": "Igaz", "isCorrect": true}, {"id": "6ab77144-7f70-449d-80b2-fea59d505c50", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "946b82fd-7b51-44b4-a583-18737402ee93", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "282df273-5ce3-4515-9d59-34ae4a217829", "text": "Igaz", "isCorrect": true}, {"id": "9049d6ea-d8ef-4ecd-813d-48f89196a413", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7bd61ba1-69ec-496f-97ef-e2a43258c641", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "dc6ce735-b407-427b-a215-84d25c5a6a32", "text": "Igaz", "isCorrect": true}, {"id": "39bacfe8-160d-4ffc-bb08-b6a315f0d208", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e32d33ff-c7c5-4a2f-8a12-db0e632aec11", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "db5df217-56d9-408c-8cc9-1fb3c6afd635", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "7c81fef2-d46f-4cac-9aec-4d0dff5fa773", "text": "Színezés", "isCorrect": false}, {"id": "45ad3c3a-a9e5-4a30-85fe-2a179c410bda", "text": "Törlés", "isCorrect": false}, {"id": "03e608a8-be57-40a3-8fe3-263a3ca7149f", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "66235d62-d47e-4258-979f-08e24c0fee10", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "63e07398-fab9-4bc0-801f-96c48998bfe3", "text": "Igaz", "isCorrect": true}, {"id": "80fc17af-39e1-4a39-af19-d1172fb65a5b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e45ca4b7-0f05-492c-8c15-69bd8b0dbf12", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('03970a28-b1bc-460e-ac58-b5b49e278f7e', '21feff02-016d-46e2-bb9d-c27495133b1b', '65. óra: Összefoglalás', 'A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "4268c74c-677a-4c46-b18c-214218d85682", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e2105972-8ec9-48fc-b92d-b94f9c67b8bd", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "870a207c-0668-4d09-8036-8f6be5ab54b2", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "a2457712-0bba-4b10-a112-3881545c52de", "text": "Igaz", "isCorrect": true}, {"id": "360097f6-e0ec-44cb-96a7-1fc736a16863", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a5d6806-aa8d-42e7-bb2f-54a440018cfd", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "7ec3b9be-c4de-4b91-92ba-a27438ad61de", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "655d6fca-322e-42c8-a827-526fa204e6db", "text": "Igaz", "isCorrect": true}, {"id": "a2473428-0a46-4922-9794-f2e4d1423340", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c63fb39f-4a3d-479b-a4d9-7e41efa94142", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3160020a-1274-4db1-8e72-65b0955afe57", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "3dff4059-003b-44d7-98f2-b62eec0e33fb", "text": "Igaz", "isCorrect": true}, {"id": "0e09782c-abf4-468f-ba54-b29a41c714e0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('797f0f58-3fad-43c7-9465-5de32e8f072a', '21feff02-016d-46e2-bb9d-c27495133b1b', '66. óra: Témazáró dolgozat', 'Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "f592b309-f146-4332-934a-52e82f39b661", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "987f50a3-3db1-4261-ba62-fa61b7628775", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "b87713a1-2619-45b8-8a4d-0b2b288ec084", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "42927271-4cc9-4632-95c2-4a0468339957", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "46cb2457-05bb-4ff9-af5e-ec71ebaef953", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "f613e5b5-0133-4bcc-8834-30acfe6cc48c", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "a954ef9e-0998-43c9-8c04-467c6f81ee76", "text": "Igaz", "isCorrect": true}, {"id": "ab080f6b-9730-4e68-8993-85236ba0dd1b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f0dbc5b0-b9c3-45c7-9994-8db3c7de5095", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "5d625567-f533-491b-80b8-21964c6b9bdc", "text": "Igaz", "isCorrect": false}, {"id": "4de3c506-c5a3-48d3-ba1f-894bff05edcb", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "8b83688c-a224-48ab-afae-bbd5efd03a8f", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "c53830c6-5041-451b-ac31-a0b51114200e", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "8af9113a-115c-4144-81a2-584289ab1ae9", "text": "Igaz", "isCorrect": true}, {"id": "37b74de9-d018-4878-be02-7b0f2606149c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "32d929b8-6412-48f6-9604-946cd7f74840", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "6202c862-d786-4004-a19c-47700a3d6638", "text": "Önmagában", "isCorrect": true}, {"id": "e8bff1fb-7695-404a-aa08-ad43a7a188b1", "text": "Az origóban", "isCorrect": false}, {"id": "0ce861a8-f88a-48e4-b7b5-fa9cf4ecb8ce", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "b55b2ef4-9c6e-4a86-93ae-954b2ffd3240", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7c1718f2-26fa-4fbd-a4cf-094a2f775e2c', '21feff02-016d-46e2-bb9d-c27495133b1b', '67. óra: Témazáró dolgozat értékelése', 'A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "82f94562-ef3c-4d17-9f6e-177388d0dc03", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "0c3c8436-79fe-4f43-9332-0956484de5e3", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "28eb27c4-925f-474b-86a1-151e453498af", "text": "A ceruza színe", "isCorrect": false}, {"id": "d7a99e36-deb6-4852-a792-2f4c72d9c17a", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "7e449e39-bab1-4329-8d9f-e8781260248b", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "2c013d9d-fb3f-4cb1-950c-f58944bac90b", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "506fca1a-f355-4a86-9b5d-9e4ada649071", "text": "Igaz", "isCorrect": true}, {"id": "961fadc0-6753-416a-a9e8-236a28d314a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "de2c7f50-1e1d-4778-9e21-346058ad6c0f", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "296b9697-4ddf-423d-bc99-3cc635a9e494", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "110358d4-0c91-46e4-bf3a-b874f9646e2a", "text": "Igaz", "isCorrect": true}, {"id": "5af07f29-7a31-4101-bd64-59467036a2fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "99814081-124b-4393-b4f2-6103eaea5764", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "ed69d3c3-02f8-405b-93dc-55c40ee4fec5", "text": "Végtelen sok", "isCorrect": true}, {"id": "1d7ad9c6-67f1-42e3-9e90-75a94e79c064", "text": "1", "isCorrect": false}, {"id": "3307a6c4-b30b-49fc-bb69-153a448bd654", "text": "2", "isCorrect": false}, {"id": "c08aa4a3-cf2f-4d99-a5b7-6de377adf6b5", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "a2d5a56a-d528-4092-8b4a-1bad314725ff", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "8e220b06-f669-47ae-a515-94bfe740a77e", "text": "Igaz", "isCorrect": true}, {"id": "c34e18c1-0a7d-4d5c-a33c-c1cc78e6502b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5fd0a2b8-34c6-431d-8977-d4633d4b0ccc", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('449d24b1-81c3-4da7-8c49-7407cdb2211b', '21feff02-016d-46e2-bb9d-c27495133b1b', '68. óra: Az arány fogalma', 'Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "cb4d084f-acc8-4e21-8741-a4bbafd8df65", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "906df972-852b-4d30-8371-a99c1296bffa", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "8dc34e6f-e399-4991-8cac-7cfe9bc984e4", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "cdcf32cf-513d-4370-8691-e709b0e8d1b8", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "5fb02424-7d46-446f-9179-1d7fdbc624ac", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "fdf09495-a958-49ac-b598-88ee951cfb38", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "5316b92a-7b85-4898-90a8-f5f164ef9cbe", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "94d3a8a6-1eb5-41ba-b0f4-6b19dea9efdb", "text": "Plusz jellel", "isCorrect": false}, {"id": "1747ba0e-ba37-4848-881e-d28c30587714", "text": "Csillaggal", "isCorrect": false}, {"id": "119fb397-cf1b-491b-83e5-f33df34b025e", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "d3da2180-124c-49ec-9621-6426ece10a7d", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "803f9d8d-681c-4d61-98a7-eab70d711ddd", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "ce1b1555-d995-4c73-86d2-a01d3b2c9592", "text": "1 : 2", "isCorrect": false}, {"id": "2cfc2383-2e2d-4236-99e7-1c8f6a95a661", "text": "3 : 2", "isCorrect": false}, {"id": "d92438c8-2927-4e5d-b887-a6f66ef621d5", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "b6e4c698-efd7-4a3e-b037-a9eb057798b2", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "e0007e77-0da7-4c1b-991f-e03ebeb35704", "text": "Igaz", "isCorrect": true}, {"id": "ce82aa1f-0396-4132-9d6c-8bf08a09899d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a72ff4e-67d8-4075-abea-e96998a7ebbb", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "f3e90c6d-98b1-4fc5-ad38-d281c78a254e", "text": "1 : 2", "isCorrect": true}, {"id": "23bcdca8-c34e-47d8-ab7e-ff8c079906fb", "text": "2 : 4", "isCorrect": false}, {"id": "3de59c87-fc1e-48ad-a350-56b7b5a6b5f4", "text": "1 : 4", "isCorrect": false}, {"id": "118540d8-c335-448f-a782-8b18d4b4b08f", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "7a82737b-93f1-49dc-a88a-45aa07b1369c", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "b9b25def-3d51-442d-9735-873c2a0ed306", "text": "Igaz", "isCorrect": true}, {"id": "0cfea216-89d8-4b02-be39-3528f182cb8b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ebd14d8a-9c4e-440b-b14f-9346531d160f", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "ba46781d-88c2-443d-b0ed-343155d5fb3a", "text": "5 : 10", "isCorrect": true}, {"id": "54d8538c-8048-4f5f-9f33-855b0a6f363a", "text": "2 : 1", "isCorrect": false}, {"id": "8909e909-9d85-477c-b1d9-c492fabd4706", "text": "3 : 5", "isCorrect": false}, {"id": "20511371-2f5c-4034-a0fe-de077eea8dbf", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('372b27f6-58f4-4c78-b1fc-8d5cb63b9116', '21feff02-016d-46e2-bb9d-c27495133b1b', '69. óra: Arányos osztás', 'Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "7bccde0c-e734-4e41-9b53-66e0eeca9154", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "74c2566d-2436-4771-b502-a6e8b29431da", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "7073767b-2be6-4765-a350-04ca47c9cd51", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "0e0259c0-d397-4afc-8486-79033e20de6d", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "bd78fc1d-3887-4d39-a344-ce9628670e1e", "text": "Igaz", "isCorrect": true}, {"id": "9f2b752b-52df-4c01-9673-b42b751f2fdb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ea7c6a90-9338-46f0-b075-db425248bc04", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "11033702-5007-402e-876c-1a4645736873", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "622abd5b-566a-4954-8616-da9630763d69", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "e84528f6-be07-48ab-8223-ab96926b23c6", "text": "Igaz", "isCorrect": true}, {"id": "6b4b9cef-0422-49db-83fb-80e11992b5d9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());